package com.ticketing.v3.performance.repository;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;import java.time.*;import static com.ticketing.v3.global.repository.Sql.*;
@Repository public class ManagementRepository {
 private final JdbcTemplate jdbc;public ManagementRepository(JdbcTemplate j){jdbc=j;}
 public long create(long owner,String title,String description,long venue,String venueName){long id=insert(jdbc,"INSERT INTO performance(owner_id,title,description,venue_id,venue_name,min_price_krw,max_price_krw,approval_status) VALUES(?,?,?,?,?,0,0,'PENDING')",owner,title,description,venue,venueName);jdbc.update("INSERT INTO performance_sale(performance_id) VALUES(?)",id);return id;}
 public Optional<Map<String,Object>> find(long id,boolean lock){return jdbc.queryForList("SELECT p.id,p.owner_id AS ownerId,p.title,COALESCE(p.description,'') AS description,p.venue_id AS venueId,p.approval_status AS approvalStatus,COALESCE(s.status,'PREPARING') AS saleStatus,s.starts_at AS saleStartsAt,s.ends_at AS saleEndsAt,p.venue_name AS venueName FROM performance p LEFT JOIN performance_sale s ON s.performance_id=p.id WHERE p.id=?"+(lock?" FOR UPDATE":""),id).stream().findFirst();}
 public List<Long> managed(Long owner){return jdbc.queryForList("SELECT id FROM performance"+(owner==null?" WHERE owner_id IS NOT NULL AND venue_id IS NOT NULL":" WHERE owner_id=? AND venue_id IS NOT NULL")+" ORDER BY id",Long.class,owner==null?new Object[]{}:new Object[]{owner});}
 public List<Map<String,Object>> catalog(String q){return jdbc.queryForList("SELECT p.id,p.title,p.venue_name AS venueName,COALESCE(MIN(ss.price_krw),p.min_price_krw) AS minPriceKrw,COALESCE(MAX(ss.price_krw),p.max_price_krw) AS maxPriceKrw FROM performance p LEFT JOIN performance_session ps ON ps.performance_id=p.id LEFT JOIN session_seat ss ON ss.session_id=ps.id WHERE p.approval_status='APPROVED' AND LOWER(p.title) LIKE ? GROUP BY p.id ORDER BY p.id","%"+q.toLowerCase(Locale.ROOT)+"%");}
 public long session(long performance,Instant startsAt){return insert(jdbc,"INSERT INTO performance_session(performance_id,starts_at) VALUES(?,?)",performance,stamp(startsAt));}
 public Long performanceForSession(long session){return jdbc.queryForList("SELECT performance_id FROM performance_session WHERE id=?",Long.class,session).stream().findFirst().orElse(null);}
 public List<Map<String,Object>> sessions(long performance,Instant now){return jdbc.queryForList("SELECT ps.id,ps.starts_at AS startsAt,COALESCE(SUM(CASE WHEN ss.status='AVAILABLE' OR(ss.status='HELD' AND h.expires_at<=?) THEN 1 ELSE 0 END),0) AS remainingSeats,COALESCE(MIN(ss.price_krw),0) AS minPriceKrw,COALESCE(MAX(ss.price_krw),0) AS maxPriceKrw FROM performance_session ps JOIN session_seat ss ON ss.session_id=ps.id LEFT JOIN seat_hold h ON h.id=ss.hold_id WHERE ps.performance_id=? GROUP BY ps.id ORDER BY ps.starts_at,ps.id",stamp(now),performance);}
 public void sale(long id,String status,Instant start,Instant end){jdbc.update("UPDATE performance_sale SET status=?,starts_at=?,ends_at=? WHERE performance_id=?",status,stamp(start),stamp(end),id);}
 public void review(long id,String decision){jdbc.update("UPDATE performance SET approval_status=? WHERE id=?",decision,id);}
}
